  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Saber, Conocer and the Personal A$j$, $j${"questions": [{"q": "To say you know a fact, use:", "options": ["Ser", "Saber", "Estar", "Conocer"]}, {"q": "Conozco a María requires the a because María is:", "options": ["A person", "A place", "A fact", "A day"]}, {"q": "Sé cantar means:", "options": ["I know the singer", "I know how to sing", "I sing the song", "I was singing"]}, {"q": "Which is correct?", "options": ["Sabo Miami", "Conozco a Miami", "Conozco Miami", "Sé Miami"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Saber, Conocer and the Personal A$j$);
